        # Fall back to a lenient parse so that unusual input still sorts.
        core, _, rest = version.partition('+')
        core, _, pre = core.partition('-')
        parts = [int(x) if x.isdigit() else 0 for x in core.split('.')]
        parts += [0] * (3 - len(parts))
        major, minor, patch = parts[:3]
        pre_str = pre
    else:
        major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
        pre_str = m.group(4) or ''

    if pre_str == '':
        # Release versions sort after any pre-release of the same core.
        pre_key = (1,)
